  private static final String SYNC = "SYNC";
  private String manageType = "";
  public FileMgmtThread (String type) {
    manageType = type;
  }
  public void run() {
    // 멀티쓰레드 환경에서 synchronized를 사용하여 동시에 접근할 수 없도록 사용해야 한다.
