code_examples.safe:
static volatile double account;
static mtx_t account_lock;

void deposit(int amount) {
  // mutex_lock, mutex_unlock을 이용해 공유 자원 접근을 제한한다.
  mutex_lock(&account_lock);
  account += amount;
  mutex_unlock(&account_lock);
}

void withdraw(int amount) {
  mutex_lock(&account_lock);
  account -= amount;
  mutex_unlock(&account_lock);
}

